/**
 * Dense arrays generated by index using monoid repetition and array map.
 *
 * @module
 */

import { repeat } from '../repeat/module.f.js'

/**
 * Returns `[f(0), ..., f(n - 1)]`, calling `f` once per index in ascending
 * order, with the index as its only argument. Zero (including negative zero)
 * produces a fresh empty array without calling `f`. Callback failures propagate.
 *
 * `n` must be an integer in the JavaScript array-length range, 0 through
 * `0xffff_ffff`. Other values throw before the callback is called. Unlike
 * `Array.from({ length: n }, ...)`, this does not coerce or round the length.
 *
 * @type {<T>(n: number, f: (index: number) => T) => readonly T[]}
 */
export const generate = (n, f) => {
    if (!Number.isInteger(n) || n < 0 || n > 0xffff_ffff) { throw 'invalid array length' }
    return repeat(n)(undefined).map((_, i) => f(i))
}
